  "0001_initial.sql": "PRAGMA foreign_keys = ON;\n\n-- =========================\n-- Users\n-- =========================\n\nCREATE TABLE users (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    email TEXT,\n    photo_url TEXT,\n    account_number TEXT,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL\n);\n\nCREATE UNIQUE INDEX idx_users_email\nON users(email)\nWHERE email IS NOT NULL;\n\n\n-- =========================\n-- Display Names\n-- =========================\n\nCREATE TABLE display_names (\n    display_name_lower TEXT PRIMARY KEY,\n    display_name TEXT NOT NULL,\n    created_at TEXT NOT NULL\n);\n\n\n-- =========================\n-- Friendships\n-- =========================\n\nCREATE TABLE friendships (\n    user_id TEXT NOT NULL,\n    friend_id TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n\n    PRIMARY KEY (user_id, friend_id),\n\n    FOREIGN KEY (user_id)\n        REFERENCES users(id)\n        ON DELETE CASCADE,\n\n    FOREIGN KEY (friend_id)\n        REFERENCES users(id)\n        ON DELETE CASCADE,\n\n    CHECK (user_id != friend_id)\n);\n\n\n-- =========================\n-- Groups\n-- =========================\n\nCREATE TABLE groups (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    created_by TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n\n    FOREIGN KEY (created_by)\n        REFERENCES users(id)\n);\n\n\n-- =========================\n-- Group Members\n-- =========================\n\nCREATE TABLE group_members (\n    group_id TEXT NOT NULL,\n    user_id TEXT NOT NULL,\n\n    PRIMARY KEY (group_id, user_id),\n\n    FOREIGN KEY (group_id)\n        REFERENCES groups(id)\n        ON DELETE CASCADE,\n\n    FOREIGN KEY (user_id)\n        REFERENCES users(id)\n        ON DELETE CASCADE\n);\n\n\n-- =========================\n-- Expenses\n-- =========================\n\nCREATE TABLE expenses (\n    id TEXT PRIMARY KEY,\n    group_id TEXT NOT NULL,\n    amount REAL NOT NULL,\n    paid_by_id TEXT NOT NULL,\n    date_time TEXT NOT NULL,\n    description TEXT NOT NULL,\n    is_equal_split INTEGER NOT NULL DEFAULT 1,\n    created_at TEXT NOT NULL,\n    updated_at TEXT NOT NULL,\n\n    CHECK (is_equal_split IN (0, 1)),\n\n    FOREIGN KEY (group_id)\n        REFERENCES groups(id)\n        ON DELETE CASCADE,\n\n    FOREIGN KEY (paid_by_id)\n        REFERENCES users(id)\n);\n\n\n-- =========================\n-- Expense Participants\n-- =========================\n\nCREATE TABLE expense_participants (\n    expense_id TEXT NOT NULL,\n    user_id TEXT NOT NULL,\n\n    PRIMARY KEY (expense_id, user_id),\n\n    FOREIGN KEY (expense_id)\n        REFERENCES expenses(id)\n        ON DELETE CASCADE,\n\n    FOREIGN KEY (user_id)\n        REFERENCES users(id)\n        ON DELETE CASCADE\n);\n\n\n-- =========================\n-- Custom Expense Splits\n-- =========================\n\nCREATE TABLE expense_splits (\n    expense_id TEXT NOT NULL,\n    user_id TEXT NOT NULL,\n    amount REAL NOT NULL,\n\n    PRIMARY KEY (expense_id, user_id),\n\n    FOREIGN KEY (expense_id)\n        REFERENCES expenses(id)\n        ON DELETE CASCADE,\n\n    FOREIGN KEY (user_id)\n        REFERENCES users(id)\n        ON DELETE CASCADE\n);\n\n\n-- =========================\n-- Indexes\n-- =========================\n\nCREATE INDEX idx_group_members_user\nON group_members(user_id);\n\nCREATE INDEX idx_groups_created_by\nON groups(created_by);\n\nCREATE INDEX idx_expenses_group\nON expenses(group_id);\n\nCREATE INDEX idx_expenses_paid_by\nON expenses(paid_by_id);\n\nCREATE INDEX idx_expense_participants_user\nON expense_participants(user_id);\n\nCREATE INDEX idx_expense_splits_user\nON expense_splits(user_id);",
